import random, json
random.seed(0)
def pair():
    a,b=random.randint(10,99),random.randint(10,99)
    return (max(a,b),min(a,b))
def make(ctrl,n=120):
    out=[]
    for _ in range(n):
        shots=[pair() for _ in range(3)]; a,b=pair()
        if ctrl:
            p="".join(f"second of {x} and {y} is {y}\n" for x,y in shots)+f"second of {a} and {b} is"; ans=f" {b}"
        else:
            p="".join(f"{x} - {y} = {x-y}\n" for x,y in shots)+f"{a} - {b} ="; ans=f" {a-b}"
        out.append({"prompt":p,"answer":ans})
    return out
json.dump({"items":make(False),"control":make(True)},open("/work/skill.json","w"))
